script:
if doc.depends_on:
	total = len(doc.depends_on)
	completed = 0
	cancelled = 0

	for row in doc.depends_on:
		if row.task:
			try:
				task = frappe.get_doc("Task", row.task)
				if task.status == "Completed":
					completed += 1
				elif task.status == "Cancelled":
					cancelled += 1
			except frappe.DoesNotExistError:
				frappe.log_error(f"Task {row.task} not found", "Subtask Progress Update")

	# Odliczamy anulowane od calkowitej liczby
	effective_total = total - cancelled

	if effective_total > 0:
		percent = int((completed / effective_total) * 100)
	else:
		percent = 0  # jesli wszystkie anulowane, postep = 0

	doc.progress = percent

	# Status nie jest juz automatycznie zmieniany na Completed na podstawie
	# postepu zaleznosci - to prowadzilo do sytuacji, w ktorej zadania z
	# ukonczonymi zaleznosciami nie dalo sie recznie otworzyc z powrotem
	# (zapis zawsze wymuszal Completed). Uzytkownik decyduje kiedy zadanie
	# jest faktycznie ukonczone, tak samo jak w rollupie podzadan w
	# events/task_events.py.
